module.exports = "const API = '/api';\nlet currentType = 'official';\nlet viewingTournamentId = null; // null = show the \"latest\" one; set = viewing a past tournament\n\nfunction showToast(text, isErr) {\n  const t = document.getElementById('toast');\n  t.textContent = text;\n  t.className = 'toast show ' + (isErr ? 'err' : 'ok');\n  setTimeout(() => t.classList.remove('show'), 2500);\n}\n\nasync function loadSettings() {\n  try {\n    const res = await fetch(`${API}/settings`);\n    const s = await res.json();\n    if (s.background_image) {\n      document.body.style.backgroundImage = `url(${s.background_image})`;\n    }\n  } catch (e) { /* non-fatal */ }\n}\n\nasync function loadPlayers() {\n  const res = await fetch(`${API}/players`);\n  const players = await res.json();\n  const row = document.getElementById('playersRow');\n  row.innerHTML = players.map(p => `\n    <div class=\"player-card glass\">\n      ${p.photo\n        ? `<img class=\"photo\" src=\"${p.photo}\" alt=\"${escapeHtml(p.name)}\">`\n        : `<div class=\"photo empty\">${escapeHtml(p.name).slice(4,6) || '?'}</div>`}\n      <div class=\"pname\">${escapeHtml(p.name)}</div>\n    </div>\n  `).join('');\n  return players;\n}\n\nfunction escapeHtml(s) {\n  return String(s || '').replace(/[&<>\"']/g, c => ({\n    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'\n  }[c]));\n}\n\nasync function loadTournamentView() {\n  const area = document.getElementById('tournamentArea');\n  let tournament;\n\n  if (viewingTournamentId) {\n    // Viewing a specific past tournament - fetch its details via the past list already loaded\n    tournament = window.__pastCache?.find(t => t.id === viewingTournamentId);\n  } else {\n    const res = await fetch(`${API}/tournaments/latest?type=${currentType}`);\n    tournament = await res.json();\n  }\n\n  if (!tournament) {\n    area.innerHTML = `<div class=\"glass t-header\"><div class=\"t-name\">No ${currentType} tournament yet</div>\n      <div class=\"t-meta\">Add one from the Admin Panel.</div></div>`;\n    document.getElementById('overallArea').innerHTML = '';\n    document.getElementById('mapArea').innerHTML = '';\n    return;\n  }\n\n  area.innerHTML = `\n    <div class=\"glass t-header\">\n      <div class=\"t-name\">🏆 ${escapeHtml(tournament.name)} ${viewingTournamentId ? '<span style=\"color:var(--muted);font-size:11px;\">(Past)</span>' : ''}</div>\n      <div class=\"t-meta\">${tournament.type.toUpperCase()} TOURNAMENT</div>\n      ${tournament.yt_link ? `<a class=\"yt-btn\" href=\"${tournament.yt_link}\" target=\"_blank\">▶ Watch Live / VOD</a>` : ''}\n    </div>\n    <div id=\"matchesArea\"></div>\n  `;\n\n  const matchesRes = await fetch(`${API}/matches?tournament_id=${tournament.id}`);\n  const matches = await matchesRes.json();\n  renderMatches(matches);\n\n  loadAnalysis(tournament.id);\n}\n\nfunction renderMatches(matches) {\n  const el = document.getElementById('matchesArea');\n  if (!matches.length) {\n    el.innerHTML = `<div class=\"glass match-block\">No match data added yet.</div>`;\n    return;\n  }\n  const byMatch = {};\n  matches.forEach(m => {\n    byMatch[m.match_number] = byMatch[m.match_number] || [];\n    byMatch[m.match_number].push(m);\n  });\n\n  el.innerHTML = Object.keys(byMatch).sort((a,b) => a-b).map(num => {\n    const rows = byMatch[num];\n    const map = rows[0].map;\n    return `\n      <div class=\"glass match-block\">\n        <span class=\"map-tag\">Match ${num} · ${escapeHtml(map)}</span>\n        <table class=\"match-table\">\n          <thead><tr><th>Player</th><th>Kills</th><th>Pos</th><th>Pts</th></tr></thead>\n          <tbody>\n            ${rows.sort((a,b) => b.total_points - a.total_points).map(r => `\n              <tr>\n                <td>${escapeHtml(r.player_name)}</td>\n                <td>${r.kills}</td>\n                <td>#${r.position}</td>\n                <td class=\"pts\">${r.total_points}</td>\n              </tr>\n            `).join('')}\n          </tbody>\n        </table>\n      </div>\n    `;\n  }).join('');\n}\n\nasync function loadAnalysis(tournamentId) {\n  const [overallRes, mapRes] = await Promise.all([\n    fetch(`${API}/analysis/overall?tournament_id=${tournamentId}`),\n    fetch(`${API}/analysis/map?tournament_id=${tournamentId}`)\n  ]);\n  const overall = await overallRes.json();\n  const mapData = await mapRes.json();\n\n  const t = overall.team;\n  document.getElementById('overallArea').innerHTML = `\n    <div class=\"stat-grid\">\n      <div class=\"stat-cell\"><div class=\"num\">${t.total_kills}</div><div class=\"lbl\">Total Kills</div></div>\n      <div class=\"stat-cell\"><div class=\"num\">${t.kd}</div><div class=\"lbl\">KD</div></div>\n      <div class=\"stat-cell\"><div class=\"num\">${t.matches_played}</div><div class=\"lbl\">Matches</div></div>\n      <div class=\"stat-cell\"><div class=\"num\">${t.booyahs}</div><div class=\"lbl\">Booyah</div></div>\n    </div>\n    ${overall.players.map(p => `\n      <div class=\"player-stat-row\">\n        ${p.photo ? `<img src=\"${p.photo}\">` : `<div style=\"width:30px;height:30px;\"></div>`}\n        <div class=\"name\">${escapeHtml(p.player_name)}</div>\n        <div class=\"mini\">${p.total_kills} kills</div>\n        <div class=\"mini\">KD ${p.kd}</div>\n        <div class=\"mini\">${p.total_points} pts</div>\n      </div>\n    `).join('')}\n  `;\n\n  document.getElementById('mapArea').innerHTML = mapData.length\n    ? mapData.map(m => `\n      <div class=\"map-row\">\n        <div class=\"mname\">${escapeHtml(m.map)}</div>\n        <div class=\"mstat\">${m.total_kills} kills</div>\n        <div class=\"mstat\">${m.booyahs} booyah</div>\n        <div class=\"mstat\">avg pos #${m.avg_position ?? '-'}</div>\n      </div>\n    `).join('')\n    : `<div style=\"padding:16px; color:var(--muted); font-size:13px;\">No map data yet.</div>`;\n}\n\nasync function loadPastTournaments() {\n  const res = await fetch(`${API}/tournaments/past?type=${currentType}`);\n  const list = await res.json();\n  window.__pastCache = list;\n  const el = document.getElementById('pastList');\n  el.innerHTML = list.length\n    ? list.map(t => `\n      <div class=\"past-item\" data-id=\"${t.id}\">\n        <div>\n          <div class=\"t-name\" style=\"font-family:'Orbitron'; font-size:13px;\">${escapeHtml(t.name)}</div>\n          <div class=\"t-meta\" style=\"font-size:11px;\">${new Date(t.created_at).toLocaleDateString()}</div>\n        </div>\n        <div style=\"color:var(--flame-2); font-size:18px;\">›</div>\n      </div>\n    `).join('')\n    : `<div style=\"color:var(--muted); padding:10px 0;\">No past ${currentType} tournaments yet.</div>`;\n\n  el.querySelectorAll('.past-item').forEach(item => {\n    item.addEventListener('click', () => {\n      viewingTournamentId = Number(item.dataset.id);\n      document.getElementById('pastModal').classList.remove('open');\n      loadTournamentView();\n    });\n  });\n}\n\ndocument.getElementById('btnOfficial').addEventListener('click', () => switchType('official'));\ndocument.getElementById('btnUnofficial').addEventListener('click', () => switchType('unofficial'));\nfunction switchType(type) {\n  currentType = type;\n  viewingTournamentId = null;\n  document.getElementById('btnOfficial').classList.toggle('active', type === 'official');\n  document.getElementById('btnUnofficial').classList.toggle('active', type === 'unofficial');\n  loadTournamentView();\n}\n\ndocument.getElementById('pastBtn').addEventListener('click', () => {\n  loadPastTournaments();\n  document.getElementById('pastModal').classList.add('open');\n});\ndocument.getElementById('closePast').addEventListener('click', () => {\n  document.getElementById('pastModal').classList.remove('open');\n});\n\nasync function init() {\n  await loadSettings();\n  await loadPlayers();\n  await loadTournamentView();\n}\ninit();\nsetInterval(() => { if (!viewingTournamentId) loadTournamentView(); }, 20000); // live refresh every 20s\n";
